head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > scrollByColumnAdaptive]<br/>GridView 에 적응형 웹(Adaptive Web)이 적용된 상태일때 가로 스크롤 시 Column 단위로 스크롤할지 설정합니다.",
    "validation" : [
        "drawType='virtual', adaptive='crosstab' 이고 모바일 및 터치 환경일때 동작해야 합니다.",
        "true 설정 시, Column 단위로 스크롤 되며 일정값이 스크롤 될때 Column 단위로 왼쪽 또는 오른쪽으로 스크롤되어야 합니다.",
        "true 설정 시, 오른쪽으로 스크롤 시 마지막 Column 이 표시될때까지 제일 오른쪽 Column 은 잘려서 표시되어야 합니다.",
        "true 설정 시, 왼쪽으로 스크롤 시 제일 왼쪽 Column 은 전체가 표시되어야 합니다.",
        "false 설정 시, 픽셀 단위로 스크롤 되며 제일 왼쪽 Column 이 접혀서 사라지거나 펼쳐지는 방식으로 스크롤되어야 합니다.",
        "미설정 시, 픽셀 단위로 스크롤 되며 제일 왼쪽 Column 이 접혀서 사라지거나 펼쳐지는 방식으로 스크롤되어야 합니다.",
        "scrollByColumnAdaptive 속성이 동작하는 조건은 drawType='virtual', adaptive='crosstab' 이고 모바일 및 터치 환경일때 적응형 웹(Adaptive Web)이 적용되어 GridView 가 행-열 전환(crosstab) 구조일때로 제한되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // con 기본값(false) 명시 설정 (gdl_boolean 코드값 : 미설정='1' / true='2' / false='3')
    con_scrollByColumnAdaptive.setValue("3");

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (scrollByColumnAdaptive 는 con 값으로 반영, adaptive/drawType/adaptiveThreshold 는 전제로 고정)
    let properties = {
        scrollByColumnAdaptive: con_scrollByColumnAdaptive.getText(),
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성 (12행 → crosstab 전치 시 가로 12개 Column 이 되어 가로 스크롤 생성)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 12);

    // target 생성 (4컬럼 = dataList col1~col4 와 정합, adaptive=crosstab 전제)
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 테스트 참고 라벨 (target 생성 전, 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] adaptive=crosstab, drawType=virtual, adaptiveThreshold=1000\n브라우저 너비가 1000px 이하일 때 좁은 화면에서 Target 재생성 시 적응형(crosstab)이 활성화되어 w2grid_adaptive_crosstab 클래스가 추가되고, 12개 데이터 행이 crosstab 전치로 가로 Column 이 되어 가로 스크롤바가 표시됨\n[절차] 화면을 좁게 한 뒤 con 에서 scrollByColumnAdaptive 값 선택 후 Target 재생성 -> 모바일/터치 환경에서 그리드를 가로로 스와이프 스크롤\n[확인] (true) Column 단위 스크롤 / 오른쪽 끝 Column 잘림 / 왼쪽 Column 전체 표시, (false/미설정) 픽셀 단위 스크롤. [적응형 상태 확인] 버튼으로 클래스 활성/옵션값 확인"', '', 'label1');

    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' adaptive="crosstab" drawType="virtual" adaptiveThreshold="1000" checkAllType="false" id="" style="width:100%;height:300px;">';
    strTarget += '<w2:caption id="caption1" value="scrollByColumnAdaptive 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 적응형 crosstab 활성 여부 + scrollByColumnAdaptive 옵션 반영값 확인
scwin.btn_adaptiveCheck_onclick = function () {
    let isAdaptive = target1.hasClass("w2grid_adaptive_crosstab");
    wf_body_bottom.getObj("scwin").setReturnValue("적응형 crosstab 활성(w2grid_adaptive_crosstab 클래스) : " + isAdaptive);
    wf_body_bottom.getObj("scwin").setReturnValue("scrollByColumnAdaptive 옵션 반영값 : " + target1.options.scrollByColumnAdaptive);
}
